package com.mutemagictrees;

import net.runelite.api.AmbientSoundEffect;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.AmbientSoundEffectCreated;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import javax.inject.Inject;
import java.util.Iterator;

@PluginDescriptor(
	name = "Mute Magic Trees",
	description = "Mutes Magic Tree ambient sound effects while allowing all other ambient sounds to continue playing",
	tags = {"sound", "magic tree", "ambient"}
)
public class MuteMagicTreesPlugin extends Plugin
{
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;

	// The ambient sound of ObjectID.MAGICTREE. There is no gameval constant for sound effects.
	// Magic trees grown in farming tree patches (e.g. ObjectID.MAGIC_TREE_FULLYGROWN_1) use this same sound.
	private static final int MAGIC_TREE_AMBIENT_SOUND_ID = 3134;

	// Set when a varbit changes, since that can turn a tree patch into a magic tree with an ambient sound
	private boolean ambientSoundsChanged;

	@Override
	protected void startUp()
	{
		// reload the scene to remove magic tree ambient sounds
		reloadScene();
	}

	@Override
	protected void shutDown()
	{
		// reload the scene to reapply magic tree ambient sounds
		reloadScene();
	}

	@Subscribe
	public void onGameStateChanged(final GameStateChanged gameStateChanged)
	{
		if (gameStateChanged.getGameState() == GameState.LOGGED_IN)
		{
			filterMagicTreeAmbientSound();
		}
	}

	@Subscribe
	public void onVarbitChanged(final VarbitChanged varbitChanged)
	{
		// Farming patches are multilocs: their existing ambient sound is updated in place when the patch varbit
		// changes, without an AmbientSoundEffectCreated event. The client applies that update after this event
		// is posted, so filter on the next client tick instead (which is still before the sound starts playing).
		ambientSoundsChanged = true;
	}

	@Subscribe
	public void onClientTick(final ClientTick clientTick)
	{
		if (ambientSoundsChanged)
		{
			ambientSoundsChanged = false;
			filterMagicTreeAmbientSound();
		}
	}

	@Subscribe
	public void onAmbientSoundEffectCreated(final AmbientSoundEffectCreated ambientSoundEffectCreated)
	{
		// a magic tree growing back after being chopped adds its sound again after the scene has loaded
		if (ambientSoundEffectCreated.getAmbientSoundEffect().getSoundEffectId() == MAGIC_TREE_AMBIENT_SOUND_ID)
		{
			filterMagicTreeAmbientSound();
		}
	}

	private void reloadScene()
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.setGameState(GameState.LOADING);
			}
		});
	}

	private void filterMagicTreeAmbientSound()
	{
		final Iterator<AmbientSoundEffect> iterator = client.getAmbientSoundEffects().iterator();

		while (iterator.hasNext())
		{
			if (iterator.next().getSoundEffectId() == MAGIC_TREE_AMBIENT_SOUND_ID)
			{
				iterator.remove();
			}
		}
	}
}

package com.mutemagictrees;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class MuteMagicTreesPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(MuteMagicTreesPlugin.class);
		RuneLite.main(args);
	}
}

package com.mutemagictrees;

import com.google.inject.Guice;
import com.google.inject.testing.fieldbinder.Bind;
import com.google.inject.testing.fieldbinder.BoundFieldModule;
import net.runelite.api.AmbientSoundEffect;
import net.runelite.api.Client;
import net.runelite.api.Deque;
import net.runelite.api.GameState;
import net.runelite.api.events.AmbientSoundEffectCreated;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import javax.inject.Inject;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class MuteMagicTreesPluginUnitTest
{
	private static final int MAGIC_TREE_SOUND = 3134;
	private static final int OTHER_SOUND = 2000;

	@Mock
	@Bind
	private Client client;

	@Mock
	@Bind
	private ClientThread clientThread;

	@Inject
	private MuteMagicTreesPlugin plugin;

	private final List<AmbientSoundEffect> sounds = new ArrayList<>();

	@Before
	public void before()
	{
		Guice.createInjector(BoundFieldModule.of(this)).injectMembers(this);

		lenient().when(client.getAmbientSoundEffects()).thenReturn(new ListDeque(sounds));
		lenient().doAnswer(invocation ->
		{
			((Runnable) invocation.getArgument(0)).run();
			return null;
		}).when(clientThread).invoke(any(Runnable.class));
	}

	@Test
	public void loggingInRemovesOnlyMagicTreeSounds()
	{
		final AmbientSoundEffect other = sound(OTHER_SOUND);
		sounds.add(sound(MAGIC_TREE_SOUND));
		sounds.add(other);
		sounds.add(sound(MAGIC_TREE_SOUND));

		plugin.onGameStateChanged(gameStateChanged(GameState.LOGGED_IN));

		assertEquals(List.of(other), sounds);
	}

	@Test
	public void otherGameStatesDoNotFilter()
	{
		sounds.add(sound(MAGIC_TREE_SOUND));

		plugin.onGameStateChanged(gameStateChanged(GameState.LOADING));

		assertEquals(1, sounds.size());
	}

	@Test
	public void createdMagicTreeSoundIsRemoved()
	{
		final AmbientSoundEffect magicTree = sound(MAGIC_TREE_SOUND);
		sounds.add(magicTree);

		plugin.onAmbientSoundEffectCreated(new AmbientSoundEffectCreated(magicTree));

		assertEquals(0, sounds.size());
	}

	@Test
	public void createdOtherSoundDoesNotFilter()
	{
		final AmbientSoundEffect other = sound(OTHER_SOUND);
		sounds.add(other);

		plugin.onAmbientSoundEffectCreated(new AmbientSoundEffectCreated(other));

		verify(client, never()).getAmbientSoundEffects();
	}

	@Test
	public void patchTurningIntoMagicTreeIsRemovedOnNextClientTick()
	{
		// a farming patch's sound starts silent and is switched to the magic tree sound in place
		final AmbientSoundEffect patch = mock(AmbientSoundEffect.class);
		when(patch.getSoundEffectId()).thenReturn(-1);
		sounds.add(patch);

		// the client posts VarbitChanged before it updates the patch's sound, so nothing should be filtered yet
		plugin.onVarbitChanged(new VarbitChanged());
		verify(client, never()).getAmbientSoundEffects();

		when(patch.getSoundEffectId()).thenReturn(MAGIC_TREE_SOUND);
		plugin.onClientTick(new ClientTick());

		assertEquals(0, sounds.size());
	}

	@Test
	public void clientTicksWithoutVarbitChangesDoNotFilter()
	{
		plugin.onClientTick(new ClientTick());
		plugin.onClientTick(new ClientTick());

		verify(client, never()).getAmbientSoundEffects();
	}

	@Test
	public void varbitChangeFiltersOnlyOnce()
	{
		plugin.onVarbitChanged(new VarbitChanged());
		plugin.onVarbitChanged(new VarbitChanged());
		plugin.onClientTick(new ClientTick());
		plugin.onClientTick(new ClientTick());

		verify(client, times(1)).getAmbientSoundEffects();
	}

	@Test
	public void startUpAndShutDownReloadSceneWhenLoggedIn()
	{
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);

		plugin.startUp();
		plugin.shutDown();

		verify(client, times(2)).setGameState(GameState.LOADING);
	}

	@Test
	public void startUpAndShutDownDoNotReloadSceneWhenLoggedOut()
	{
		when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);

		plugin.startUp();
		plugin.shutDown();

		verify(client, never()).setGameState(any(GameState.class));
	}

	private static AmbientSoundEffect sound(final int soundEffectId)
	{
		final AmbientSoundEffect sound = mock(AmbientSoundEffect.class);
		lenient().when(sound.getSoundEffectId()).thenReturn(soundEffectId);
		return sound;
	}

	private static GameStateChanged gameStateChanged(final GameState gameState)
	{
		final GameStateChanged event = new GameStateChanged();
		event.setGameState(gameState);
		return event;
	}

	/**
	 * Minimal client Deque backed by a list, whose iterator supports removal like the real one.
	 */
	private static final class ListDeque implements Deque<AmbientSoundEffect>
	{
		private final List<AmbientSoundEffect> list;

		private ListDeque(final List<AmbientSoundEffect> list)
		{
			this.list = list;
		}

		@Override
		public void addLast(final AmbientSoundEffect value)
		{
			list.add(value);
		}

		@Override
		public void clear()
		{
			list.clear();
		}

		@Override
		public Iterator<AmbientSoundEffect> iterator()
		{
			return list.iterator();
		}
	}
}
